class _PigeonCodec extends StandardMessageCodec {
  const _PigeonCodec();
  @override
  void writeValue(WriteBuffer buffer, Object? value) {
    if (value is int) {
      buffer.putUint8(4);
      buffer.putInt64(value);
    } else if (value is VersolaSessionStateMessage) {
      buffer.putUint8(129);
      writeValue(buffer, value.index);
    } else if (value is VersolaUnlockPolicyMessage) {
      buffer.putUint8(130);
      writeValue(buffer, value.index);
    } else if (value is VersolaPromptMessage) {
      buffer.putUint8(131);
      writeValue(buffer, value.index);
    } else if (value is VersolaErrorCategoryMessage) {
      buffer.putUint8(132);
      writeValue(buffer, value.index);
    } else if (value is VersolaRetryPolicyMessage) {
      buffer.putUint8(133);
      writeValue(buffer, value.encode());
    } else if (value is VersolaConfigurationMessage) {
      buffer.putUint8(134);
      writeValue(buffer, value.encode());
    } else if (value is VersolaLoginOptionsMessage) {
      buffer.putUint8(135);
      writeValue(buffer, value.encode());
    } else if (value is VersolaLogoutOptionsMessage) {
      buffer.putUint8(136);
      writeValue(buffer, value.encode());
    } else if (value is VersolaErrorMessage) {
      buffer.putUint8(137);
      writeValue(buffer, value.encode());
    } else if (value is VersolaIdTokenClaimsMessage) {
      buffer.putUint8(138);
      writeValue(buffer, value.encode());
    } else if (value is VersolaLogoutOutcomeMessage) {
      buffer.putUint8(139);
      writeValue(buffer, value.encode());
    } else if (value is VersolaVoidOk) {
      buffer.putUint8(140);
      writeValue(buffer, value.encode());
    } else if (value is VersolaVoidFailure) {
      buffer.putUint8(141);
      writeValue(buffer, value.encode());
    } else if (value is VersolaCreateOk) {
      buffer.putUint8(142);
      writeValue(buffer, value.encode());
    } else if (value is VersolaCreateFailure) {
      buffer.putUint8(143);
      writeValue(buffer, value.encode());
    } else if (value is VersolaSessionStateOk) {
      buffer.putUint8(144);
      writeValue(buffer, value.encode());
    } else if (value is VersolaSessionStateFailure) {
      buffer.putUint8(145);
      writeValue(buffer, value.encode());
    } else if (value is VersolaClaimsOk) {
      buffer.putUint8(146);
      writeValue(buffer, value.encode());
    } else if (value is VersolaClaimsFailure) {
      buffer.putUint8(147);
      writeValue(buffer, value.encode());
    } else if (value is VersolaLogoutOk) {
      buffer.putUint8(148);
      writeValue(buffer, value.encode());
    } else if (value is VersolaLogoutFailure) {
      buffer.putUint8(149);
      writeValue(buffer, value.encode());
    } else if (value is VersolaKeyAttestationOk) {
      buffer.putUint8(150);
      writeValue(buffer, value.encode());
    } else if (value is VersolaKeyAttestationFailure) {
      buffer.putUint8(151);
      writeValue(buffer, value.encode());
    } else if (value is VersolaHttpHeaderMessage) {
      buffer.putUint8(152);
      writeValue(buffer, value.encode());
    } else if (value is VersolaHttpRequestMessage) {
      buffer.putUint8(153);
      writeValue(buffer, value.encode());
    } else if (value is VersolaHttpResponseMessage) {
      buffer.putUint8(154);
      writeValue(buffer, value.encode());
    } else if (value is VersolaHttpOk) {
      buffer.putUint8(155);
      writeValue(buffer, value.encode());
    } else if (value is VersolaHttpFailure) {
      buffer.putUint8(156);
      writeValue(buffer, value.encode());
    } else if (value is VersolaHttpTransportFailure) {
      buffer.putUint8(157);
      writeValue(buffer, value.encode());
    } else {
      super.writeValue(buffer, value);
    }
