  @override
  Object? readValueOfType(int type, ReadBuffer buffer) {
    switch (type) {
      case 129:
        final value = readValue(buffer) as int?;
        return value == null ? null : VersolaSessionStateMessage.values[value];
      case 130:
        final value = readValue(buffer) as int?;
        return value == null ? null : VersolaUnlockPolicyMessage.values[value];
      case 131:
        final value = readValue(buffer) as int?;
        return value == null ? null : VersolaPromptMessage.values[value];
