        return VersolaHttpOk.decode(readValue(buffer)!);
      case 156:
        return VersolaHttpFailure.decode(readValue(buffer)!);
      case 157:
        return VersolaHttpTransportFailure.decode(readValue(buffer)!);
      default:
        return super.readValueOfType(type, buffer);
    }
  }
}

